<?php
/**
 * Landing page for links generated by api/password.php.
 *   index.php?action=reset&token=...&username=...
 *   index.php?action=activate&token=...&username=...
 * Everything else redirects to the app.
 */

$action = (string) ($_GET['action'] ?? '');
$token = (string) ($_GET['token'] ?? '');
$username = (string) ($_GET['username'] ?? '');

if ($action === 'activate' && $token !== '' && $username !== '') {
    $message = 'This activation link is invalid or has already been used.';
    $ok = false;
    try {
        require_once __DIR__ . '/api/database.php';
        $db = Database::getInstance();
        $stmt = $db->prepare("SELECT username, is_active FROM users WHERE LOWER(username) = LOWER(?) AND activation_token = ? LIMIT 1");
        $stmt->execute([$username, $token]);
        $user = $stmt->fetch();
        if ($user) {
            if ((int) $user['is_active'] === 1) {
                $message = 'This account is already active. You can log in now.';
                $ok = true;
            } else {
                $stmt = $db->prepare("UPDATE users SET is_active = 1, activation_token = '' WHERE username = ?");
                $stmt->execute([$user['username']]);
                $message = 'Your account is activated. You can log in now.';
                $ok = true;
            }
        }
        $db->close();
    } catch (Throwable $e) {
        $message = 'The activation link could not be processed. Try logging in, or request a new link.';
    }
    render_message('Account activation', $message, $ok);
    exit;
}

if ($action === 'reset' && $token !== '') {
    render_reset($token);
    exit;
}

header('Location: messnger.html');
exit;

function page_head(string $title): void
{
    echo '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8">';
    echo '<meta name="viewport" content="width=device-width, initial-scale=1.0">';
    echo '<title>' . htmlspecialchars($title, ENT_QUOTES) . ' — JohnsonChat</title>';
    echo '<link rel="icon" href="data:image/svg+xml,<svg xmlns=\'http://www.w3.org/2000/svg\' viewBox=\'0 0 100 100\'><rect width=\'100\' height=\'100\' rx=\'50\' fill=\'%23e94560\'/><text x=\'50\' y=\'68\' font-size=\'50\' text-anchor=\'middle\' fill=\'white\' font-family=\'sans-serif\' font-weight=\'bold\'>J</text></svg>">';
    echo <<<'CSS'
<style>
  * { box-sizing: border-box; }
  body { margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    background: linear-gradient(135deg, #0f0c29 0%, #1a1a2e 50%, #16213e 100%); color: #eee; padding: 20px; }
  .card { width: 100%; max-width: 420px; background: rgba(22, 33, 62, 0.92); border: 1px solid rgba(233, 69, 96, 0.2);
    border-radius: 16px; padding: 36px; box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4); }
  h1 { margin: 0 0 12px; font-size: 24px; background: linear-gradient(135deg, #e94560, #ff6b6b);
    -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
  p { line-height: 1.5; color: #b9c2d0; font-size: 14px; }
  label { display: block; margin: 16px 0 6px; font-size: 12px; text-transform: uppercase; letter-spacing: .06em; color: #8d99ad; }
  input { width: 100%; padding: 12px 14px; border-radius: 10px; border: 1px solid rgba(255, 255, 255, 0.14);
    background: rgba(15, 52, 96, 0.5); color: #fff; font-size: 15px; outline: none; }
  input:focus { border-color: #e94560; }
  button { width: 100%; margin-top: 20px; padding: 12px; border: 0; border-radius: 10px; cursor: pointer;
    background: #e94560; color: #fff; font-weight: 700; font-size: 15px; }
  button:disabled { opacity: .6; cursor: default; }
  .error { margin-top: 14px; padding: 10px 12px; border-radius: 8px; background: rgba(233, 69, 96, 0.12);
    color: #ff8a9a; font-size: 13px; display: none; }
  .ok { color: #7fe0a0; }
  a { color: #4fc3f7; }
  .foot { margin-top: 18px; text-align: center; font-size: 13px; }
</style>
CSS;
    echo '</head><body><div class="card">';
}

function page_foot(): void
{
    echo '<p class="foot"><a href="messnger.html">Back to JohnsonChat</a></p></div></body></html>';
}

function render_message(string $title, string $message, bool $ok): void
{
    page_head($title);
    echo '<h1>' . htmlspecialchars($title, ENT_QUOTES) . '</h1>';
    echo '<p class="' . ($ok ? 'ok' : '') . '">' . htmlspecialchars($message, ENT_QUOTES) . '</p>';
    echo '<a href="messnger.html"><button type="button">Continue to login</button></a>';
    page_foot();
}

function render_reset(string $token): void
{
    page_head('Reset password');
    $safeToken = htmlspecialchars($token, ENT_QUOTES);
    echo '<h1>Set a new password</h1>';
    echo '<p>Choose a password for your account. This link expires one hour after it was requested.</p>';
    echo '<form id="reset-form" data-token="' . $safeToken . '">';
    echo '<label for="pw">New password</label><input id="pw" type="password" minlength="6" maxlength="72" autocomplete="new-password" required>';
    echo '<label for="pw2">Confirm password</label><input id="pw2" type="password" minlength="6" maxlength="72" autocomplete="new-password" required>';
    echo '<div id="err" class="error"></div>';
    echo '<button id="submit" type="submit">Update password</button>';
    echo '</form>';
    echo '<p class="foot"><a href="messnger.html">Back to JohnsonChat</a></p></div>';
    echo '<script src="reset.js"></script></body></html>';

}
